Configuration.parameter:
// Sample connector
// Place intialiazation code before function declarations.
//

var fileName = "examples/script_connector/lookup_in.txt";
var input;
var output;


// Attempts to read an Entry from the file.
// Returns the Entry object if successfuly read, null otherwise.
function readEntry ()
{
	var line;
	var aEntry = system.newEntry ();
	do {
		line = input.readLine ();
		if ( line == null ) {
			break;
		}

		if ( ! line.equals(".") ) {
			parseAttributeValue ( String ( line ), aEntry );
		}
	}
	while ( ! line.equals(".") );

	if ( line == null ) {
		return null;
	} 
	else {
		return aEntry;
	}
}

// Parses an AttributeValue and adds it to the aEntry parameter
function parseAttributeValue ( line, aEntry )
{
	var indOfColon = line.indexOf ( ":" );
	var attrName = line.substr ( 0, indOfColon );
	var attrValue = line.substr ( indOfColon + 1, line.length - indOfColon - 1 );

	aEntry.addAttributeValue ( attrName, attrValue );
}


function selectEntries ()
{
	input = system.openFileForInput(fileName);
}


function getNextEntry ()
{
	var aEntry = readEntry ();

	if ( aEntry != null ) {
		entry.merge ( aEntry );
	}
	else {
		input.close ();		
		result.setStatus ( 0 );
		result.setMessage ( "End of input" );
	} 
}


function putEntry ()
{
	output = system.openFileForAppend ( fileName );

	var names = entry.getAttributeNames ();
    for( var i = 0; i < names.length; i++ ) {
    	var attribute = entry.getAttribute ( names[i] );
        for ( var j = 0; j < attribute.size(); j++ ) {
           	output.write ( attribute.getName () + ":" + attribute.getValue ( j ) );
			output.newLine ();
		}
    }
	output.write ( "." );
	output.newLine ();

	output.close ();
}


function findEntry ()
{
	input = system.openFileForInput ( fileName );

	var isFound = false;
	do {
		var match = true;
		var aEntry = readEntry ();

		if (aEntry != null) {
			for ( var i = 0; i < search.size (); i++ ) {
				var sc = search.getCriteria ( i );
				var attrValue = aEntry.getAttribute ( sc.name ).getValue ();

				if ( ( sc.match != 61 ) || (! attrValue.equals( sc.value ) ) ) {  // 61 is the code of the '=' symbol
					match = false;
					break;
				}				
			}
			isFound = match;
		}
	}
	while ( ( aEntry != null ) && ( isFound == false ) );

	if ( isFound == true ) {
		entry.merge ( aEntry );
		result.setStatus ( 1 );
	}
	else {
		result.setStatus ( 0 );
	}

	input.close ();
}


function modEntry ()
{
}


function deleteEntry ()
{
}

